const PptxGenJS = require('/home/node/workspace/node_modules/pptxgenjs');
const fs = require('fs');
const data = JSON.parse(fs.readFileSync('/home/node/workspace/results/ma-slides-v2.json', 'utf8'));
const pptx = new PptxGenJS();
pptx.layout = 'LAYOUT_WIDE';
pptx.title = data.title;
data.slides.forEach((s, i) => {
  const slide = pptx.addSlide();
  slide.background = { color: '0F0F19' };
  slide.addText(s.title, { x:0.6, y:0.25, w:12.1, h:0.85, fontSize:32, bold:true, color:'FFFFFF', fontFace:'Calibri' });
  slide.addText(s.headline, { x:0.65, y:1.15, w:12, h:0.65, fontSize:18, italic:true, color:'63B3ED', fontFace:'Calibri' });
  const bulletObjs = (s.bullets||[]).map(b => ({
    text: b,
    options: { bullet: { type: 'bullet' }, fontSize: 16, color: 'DCDCDC', fontFace: 'Calibri', paraSpaceAfter: 8 }
  }));
  if (bulletObjs.length) slide.addText(bulletObjs, { x:0.9, y:2.0, w:11.5, h:4.6, valign:'top' });
  slide.addText((i+1) + ' / ' + data.slides.length, { x:11.8, y:7.05, w:1.4, h:0.25, fontSize:11, color:'646478', align:'right' });
  if (s.notes) slide.addNotes(s.notes);
});
pptx.writeFile({ fileName: '/home/node/workspace/results/ma-explainer-v2.pptx' })
  .then(() => { console.log('saved'); })
  .catch(e => { console.error(e.message); process.exit(1); });
